using System; namespace KeyJaya {public static class WordRangeTests {
 public static int Main(){int passed=0;foreach(string word in new[]{"raja","Earlier untouched raja and Krsna.","ā","a\nb"}){if(SelectionFormatting.WordOwnedLength(word,word,word.Length)!=word.Length)throw new Exception("exact selection");passed++;if(SelectionFormatting.WordOwnedLength(word,word+"\n",word.Length+1)!=word.Length)throw new Exception("terminal paragraph");passed++;foreach(string extra in new[]{"x","\n\n","\a"," \n"}){if(SelectionFormatting.WordOwnedLength(word,word+extra,word.Length+extra.Length)!=-1)throw new Exception("extra text accepted");passed++;}if(SelectionFormatting.WordOwnedLength(word,word+"\n",word.Length)!=-1)throw new Exception("wrong COM length accepted");passed++;}Console.WriteLine("PASS: "+passed+" FAIL: 0");return 0;}
}}
